SOURCE_TABLES=["sources","source_revisions","sections","entity_versions"]
V4_TABLES=["phase8_rule_registry","phase8_rule_family_links","phase8_baseline_batches"]
EXPECTED={"registry":70,"family_links":77,"v4_backlog":67,"profiles":19,"profile_links":26,
"resolutions":67,"structured":26,"reference":25,"quarantine":16,"backlog_after":0}
def now_iso():return datetime.now(timezone.utc).isoformat()
def ocr_norm(text):
    text=str(text or "")
    text=text.replace("\u00ad","")
    text=re.sub(r'(?<=\w)[\-\u2010\u2011\u2012\u2013\u2014]\s+(?=\w)',"",text)
    import unicodedata
    text=unicodedata.normalize("NFKD",text)
    text="".join(ch for ch in text if not unicodedata.combining(ch))
    text=re.sub(r"[^A-Za-z0-9%]+"," ",text)
    return re.sub(r"\s+"," ",text).strip().lower()

def guard_match(pattern,text):
    if re.search(pattern,text or "",re.I|re.S):
        return True
    if not re.search(r'[\[\]().?*+|\\^$]',pattern):
        return ocr_norm(pattern) in ocr_norm(text)
    return False

def cjson(v):return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":"))
def logical_digest(db,table):
    cols=[r[1] for r in db.execute(f'PRAGMA table_info("{table}")')]
    if not cols:raise RuntimeError(f"Missing table for digest: {table}")
    sel=", ".join(f'"{c}"' for c in cols);h=hashlib.sha256()
    for row in db.execute(f'SELECT {sel} FROM "{table}" ORDER BY rowid'):
        h.update(cjson(list(row)).encode("utf-8"));h.update(b"\n")
    return h.hexdigest()
def section_digest(db,section_id):
    row=db.execute("""SELECT s.id,s.revision_id,s.heading,s.body,s.page_start,s.page_end,
    src.id,src.title,src.rules_version,src.current_revision_id FROM sections s
    JOIN phase8_rule_registry r ON r.section_id=s.id JOIN sources src ON src.id=r.source_id
    WHERE s.id=?""",(section_id,)).fetchone()
    if not row:raise RuntimeError(f"Missing section {section_id}")
    return hashlib.sha256(cjson(list(row)).encode("utf-8")).hexdigest()
def phase7_dependency():
    db=sqlite3.connect(f"file:{MONSTERS_DB.as_posix()}?mode=ro",uri=True)
    try:
        backlog=db.execute("SELECT COUNT(*) FROM phase7_monster_automation_backlog").fetchone()[0]
        batch=db.execute("""SELECT phase_status,package_version,backlog_after FROM phase7_v10_batches
        ORDER BY created_at DESC LIMIT 1""").fetchone()
        if not (backlog==0 and batch and tuple(batch)==("FINAL_RESIDUALS_CLASSIFIED_READY_FOR_PHASE7_CLOSURE","V10_FIXED",0)):
            raise RuntimeError("Phase 7 closure dependency failed.")
    finally:db.close()
def pairset(items):return {(x["section_id"],x["family"]) for x in items}
def preconditions(db):
    integrity=db.execute("PRAGMA integrity_check").fetchone()[0];fk=db.execute("PRAGMA foreign_key_check").fetchall()
    if integrity!="ok":raise RuntimeError(f"integrity={integrity}")
    if fk:raise RuntimeError(f"foreign_keys={len(fk)}")
    tables={r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    needed=set(SOURCE_TABLES+V4_TABLES+["phase8_automation_backlog"])
    missing=sorted(needed-tables)
    if missing:raise RuntimeError(f"Missing tables: {missing}")
    v7={"phase8_semantic_profiles","phase8_semantic_profile_links","phase8_v7_resolution_log","phase8_quarantine","phase8_v7_batches"}
    existing=sorted(v7&tables)
    if existing:raise RuntimeError(f"V7 already appears applied: {existing}")
    counts={"registry":db.execute("SELECT COUNT(*) FROM phase8_rule_registry").fetchone()[0],
    "family_links":db.execute("SELECT COUNT(*) FROM phase8_rule_family_links").fetchone()[0],
    "v4_backlog":db.execute("SELECT COUNT(*) FROM phase8_automation_backlog").fetchone()[0]}
    for k in counts:
        if counts[k]!=EXPECTED[k]:raise RuntimeError(f"V4 baseline drift {k} expected={EXPECTED[k]} actual={counts[k]}")
    batch=db.execute("""SELECT phase_status,package_version,backlog_rows FROM phase8_baseline_batches
    ORDER BY created_at DESC LIMIT 1""").fetchone()
    if not batch or tuple(batch)!=("STRUCTURED_BASELINE_APPLIED_PHASE8_OPEN","V4",67):
        raise RuntimeError(f"V4 batch drift {tuple(batch) if batch else None}")
    live={(r[0],r[1]) for r in db.execute("""SELECT section_id,family FROM phase8_automation_backlog
    WHERE gap_type='semantic_extraction' AND status='PENDING_SEMANTIC_EXTRACTION'""")}
    expected=pairset(STRICT)|pairset(REFERENCE)|pairset(QUARANTINE)
    if live!=expected:raise RuntimeError(f"V4 backlog pair drift missing={len(expected-live)} extra={len(live-expected)}")
    for item in STRICT+REFERENCE+QUARANTINE:
        row=db.execute("""SELECT r.source_title,r.page_start,r.heading,r.source_section_digest,l.disposition
        FROM phase8_rule_registry r JOIN phase8_rule_family_links l
        ON l.section_id=r.section_id AND l.family=? WHERE r.section_id=?""",(item["family"],item["section_id"])).fetchone()
        if not row:raise RuntimeError(f"Missing manifest pair {item['family']}:{item['section_id']}")
        if row[0]!=item["source_title"] or row[1]!=item["page_start"] or row[2]!=item["heading"]:
            raise RuntimeError(f"Source identity drift {item['family']}:{item['section_id']}")
        if row[4]!="STRUCTURED_RULE_CANDIDATE":raise RuntimeError(f"Unexpected V4 disposition {item['family']}:{item['section_id']}={row[4]}")
        if section_digest(db,item["section_id"])!=row[3]:raise RuntimeError(f"Source section digest drift {item['section_id']}")
    for key,spec in PROFILES.items():
        body=db.execute("SELECT body FROM sections WHERE id=?",(spec["section_id"],)).fetchone()[0] or ""
        missing_guards=[pat for pat in spec["guards"] if not guard_match(pat,body)]
        if missing_guards:
            diagnostic={"semantic_key":key,"missing_guards":missing_guards,"normalized_body_excerpt":ocr_norm(body)[:1200]}
            raise RuntimeError("Strict semantic evidence guard failed: "+cjson(diagnostic))
def apply(db,output):
    phase7_dependency();preconditions(db)
    source_before={t:logical_digest(db,t) for t in SOURCE_TABLES}
    v4_before={t:logical_digest(db,t) for t in V4_TABLES}
    db.executescript("""
    CREATE TABLE phase8_semantic_profiles(
      semantic_key TEXT PRIMARY KEY,section_id TEXT NOT NULL,kind TEXT NOT NULL,automation_scope TEXT NOT NULL,
      profile_json TEXT NOT NULL,source_section_digest TEXT NOT NULL,created_at TEXT NOT NULL,
      FOREIGN KEY(section_id) REFERENCES phase8_rule_registry(section_id));
    CREATE TABLE phase8_semantic_profile_links(
      section_id TEXT NOT NULL,family TEXT NOT NULL,semantic_key TEXT NOT NULL,created_at TEXT NOT NULL,
      PRIMARY KEY(section_id,family),FOREIGN KEY(section_id,family) REFERENCES phase8_rule_family_links(section_id,family),
      FOREIGN KEY(semantic_key) REFERENCES phase8_semantic_profiles(semantic_key));
    CREATE TABLE phase8_v7_resolution_log(
      section_id TEXT NOT NULL,family TEXT NOT NULL,
      disposition TEXT NOT NULL CHECK(disposition IN ('STRUCTURED_SOURCE','REFERENCE_CONTEXT_ONLY','QUARANTINED')),
      reason TEXT NOT NULL,semantic_key TEXT,created_at TEXT NOT NULL,PRIMARY KEY(section_id,family),
      FOREIGN KEY(section_id,family) REFERENCES phase8_rule_family_links(section_id,family),
      FOREIGN KEY(semantic_key) REFERENCES phase8_semantic_profiles(semantic_key));
    CREATE TABLE phase8_quarantine(
      section_id TEXT NOT NULL,family TEXT NOT NULL,reason TEXT NOT NULL,evidence_json TEXT NOT NULL,created_at TEXT NOT NULL,
      PRIMARY KEY(section_id,family),FOREIGN KEY(section_id,family) REFERENCES phase8_rule_family_links(section_id,family));
    CREATE TABLE phase8_v7_batches(
      id TEXT PRIMARY KEY,created_at TEXT NOT NULL,semantic_profiles INTEGER NOT NULL,semantic_profile_links INTEGER NOT NULL,
      resolution_rows INTEGER NOT NULL,structured_rows INTEGER NOT NULL,reference_rows INTEGER NOT NULL,
      quarantine_rows INTEGER NOT NULL,backlog_after INTEGER NOT NULL,sources_digest TEXT NOT NULL,
      source_revisions_digest TEXT NOT NULL,sections_digest TEXT NOT NULL,entity_versions_digest TEXT NOT NULL,
      v4_registry_digest TEXT NOT NULL,v4_family_links_digest TEXT NOT NULL,v4_baseline_batches_digest TEXT NOT NULL,
      phase_status TEXT NOT NULL,package_version TEXT NOT NULL);
    """)
    for key,spec in sorted(PROFILES.items()):
        profile={"schema_version":"phase8.semantic.v1","semantic_key":key,"kind":spec["kind"],
        "automation_scope":spec["automation_scope"],"facts":spec["facts"],
        "source":{"section_id":spec["section_id"],"source_title":spec["source_title"],"heading":spec["heading"],"rules_version":"2024"},
        "guard_policy":"all evidence guards matched current source at migration time"}
        db.execute("INSERT INTO phase8_semantic_profiles VALUES (?,?,?,?,?,?,?)",
        (key,spec["section_id"],spec["kind"],spec["automation_scope"],cjson(profile),section_digest(db,spec["section_id"]),now_iso()))
    for item in STRICT:
        db.execute("INSERT INTO phase8_semantic_profile_links VALUES (?,?,?,?)",
        (item["section_id"],item["family"],item["semantic_key"],now_iso()))
        db.execute("INSERT INTO phase8_v7_resolution_log VALUES (?,?,?,?,?,?)",
        (item["section_id"],item["family"],"STRUCTURED_SOURCE",item["reason"],item["semantic_key"],now_iso()))
    for item in REFERENCE:
        db.execute("INSERT INTO phase8_v7_resolution_log VALUES (?,?,?,?,?,?)",
        (item["section_id"],item["family"],"REFERENCE_CONTEXT_ONLY",item["reason"],None,now_iso()))
    for item in QUARANTINE:
        evidence={"section_id":item["section_id"],"family":item["family"],"heading":item["heading"],
        "source_title":item["source_title"],"page_start":item["page_start"],
        "expected_v5_evidence_class":item["expected_v5_evidence_class"],"reason":item["reason"]}
        db.execute("INSERT INTO phase8_v7_resolution_log VALUES (?,?,?,?,?,?)",
        (item["section_id"],item["family"],"QUARANTINED",item["reason"],None,now_iso()))
        db.execute("INSERT INTO phase8_quarantine VALUES (?,?,?,?,?)",
        (item["section_id"],item["family"],item["reason"],cjson(evidence),now_iso()))
    resolution_pairs={(r[0],r[1]) for r in db.execute("SELECT section_id,family FROM phase8_v7_resolution_log")}
    original_pairs=pairset(STRICT)|pairset(REFERENCE)|pairset(QUARANTINE)
    if resolution_pairs!=original_pairs:raise RuntimeError("Refusing backlog clear: V7 resolution pair set is incomplete.")
    db.execute("DELETE FROM phase8_automation_backlog")
    counts={"profiles":db.execute("SELECT COUNT(*) FROM phase8_semantic_profiles").fetchone()[0],
    "profile_links":db.execute("SELECT COUNT(*) FROM phase8_semantic_profile_links").fetchone()[0],
    "resolutions":db.execute("SELECT COUNT(*) FROM phase8_v7_resolution_log").fetchone()[0],
    "structured":db.execute("SELECT COUNT(*) FROM phase8_v7_resolution_log WHERE disposition='STRUCTURED_SOURCE'").fetchone()[0],
    "reference":db.execute("SELECT COUNT(*) FROM phase8_v7_resolution_log WHERE disposition='REFERENCE_CONTEXT_ONLY'").fetchone()[0],
    "quarantine":db.execute("SELECT COUNT(*) FROM phase8_v7_resolution_log WHERE disposition='QUARANTINED'").fetchone()[0],
    "backlog_after":db.execute("SELECT COUNT(*) FROM phase8_automation_backlog").fetchone()[0]}
    for k,v in counts.items():
        if v!=EXPECTED[k]:raise RuntimeError(f"V7 count mismatch {k} expected={EXPECTED[k]} actual={v}")
    source_after={t:logical_digest(db,t) for t in SOURCE_TABLES}
    v4_after={t:logical_digest(db,t) for t in V4_TABLES}
    if source_before!=source_after:raise RuntimeError("Canonical source tables changed during V7.")
    if v4_before!=v4_after:raise RuntimeError("V4 baseline tables changed during V7.")
    batch_id="phase8-v7-"+datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    db.execute("INSERT INTO phase8_v7_batches VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
    (batch_id,now_iso(),counts["profiles"],counts["profile_links"],counts["resolutions"],counts["structured"],
    counts["reference"],counts["quarantine"],counts["backlog_after"],source_after["sources"],source_after["source_revisions"],
    source_after["sections"],source_after["entity_versions"],v4_after["phase8_rule_registry"],v4_after["phase8_rule_family_links"],
    v4_after["phase8_baseline_batches"],"STRICT_SEMANTICS_RESOLVED_PHASE8_READY_FOR_FINAL_AUDIT","V7_FIXED3"))
    fk=db.execute("PRAGMA foreign_key_check").fetchall()
    if fk:raise RuntimeError(f"V7 introduced foreign-key errors={len(fk)}")
    output.mkdir(parents=True,exist_ok=True)
    report={"package":"PHASE8_STRICT_SEMANTIC_RESOLUTION_V7_FIXED3","semanticProfiles":counts["profiles"],
    "semanticProfileLinks":counts["profile_links"],"resolutionRows":counts["resolutions"],
    "structuredRows":counts["structured"],"referenceRows":counts["reference"],"quarantineRows":counts["quarantine"],
    "automationBacklog":counts["backlog_after"],"sourceTablesUnchanged":True,"v4BaselineTablesUnchanged":True,
    "phaseStatus":"STRICT_SEMANTICS_RESOLVED_PHASE8_READY_FOR_FINAL_AUDIT","next":"PHASE8_FINAL_CLOSURE_AUDIT_V8"}
    (output/"phase8_strict_semantic_resolution_v7_report.json").write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    (output/"PHASE8_STRICT_SEMANTIC_RESOLUTION_V7_SUMMARY.md").write_text(
    "# Phase 8 — Strict Semantic Resolution V7\n\n"
    f"- Semantic profiles: {counts['profiles']}\n- Strict profile links: {counts['profile_links']}\n"
    f"- Resolution rows: {counts['resolutions']}\n- Structured source: {counts['structured']}\n"
    f"- Reference/context only: {counts['reference']}\n- Quarantined: {counts['quarantine']}\n"
    f"- Active automation backlog: {counts['backlog_after']}\n\n"
    "Quarantined rows remain explicit unresolved/source-shape limitations and are not treated as structured semantics.\n\n"
    "**Status: STRICT_SEMANTICS_RESOLVED_PHASE8_READY_FOR_FINAL_AUDIT**\n",encoding="utf-8")
    return report
def main():
    ap=argparse.ArgumentParser();ap.add_argument("--db",default=str(RULES_DB));ap.add_argument("--output",default=str(DEFAULT_OUTPUT));ap.add_argument("--apply",action="store_true")
    args=ap.parse_args();db=sqlite3.connect(args.db,timeout=10);db.execute("PRAGMA foreign_keys=ON")
    try:
        phase7_dependency();preconditions(db)
        if not args.apply:print("PHASE8_V7_PRECHECK=PASS");return 0
        db.execute("BEGIN IMMEDIATE")
        try:report=apply(db,Path(args.output));db.commit()
        except Exception:db.rollback();raise
        integrity=db.execute("PRAGMA integrity_check").fetchone()[0];fk=db.execute("PRAGMA foreign_key_check").fetchall()
        if integrity!="ok" or fk:raise RuntimeError(f"Post-V7 check failed integrity={integrity} fk={len(fk)}")
        print("PHASE 8 STRICT SEMANTIC RESOLUTION V7 APPLIED")
        print(f"SEMANTIC_PROFILES={report['semanticProfiles']}");print(f"SEMANTIC_PROFILE_LINKS={report['semanticProfileLinks']}")
        print(f"RESOLUTION_ROWS={report['resolutionRows']}");print(f"STRUCTURED_SOURCE={report['structuredRows']}")
        print(f"REFERENCE_CONTEXT_ONLY={report['referenceRows']}");print(f"QUARANTINED={report['quarantineRows']}")
        print(f"AUTOMATION_BACKLOG={report['automationBacklog']}");print("SOURCE_TABLES_UNCHANGED=YES")
        print("V4_BASELINE_TABLES_UNCHANGED=YES");print("INTEGRITY=ok");print("FOREIGN_KEYS=0")
        print("PHASE_STATUS=STRICT_SEMANTICS_RESOLVED_PHASE8_READY_FOR_FINAL_AUDIT")
        print("NEXT=PHASE8_FINAL_CLOSURE_AUDIT_V8");print(f"OUTPUT={args.output}");return 0
    finally:db.close()
if __name__=="__main__":raise SystemExit(main())
